#define main update_bench_main
#include "update-path-bench.c"
#undef main
#include <float.h>
typedef struct {sds key; double score;} item;
static int compare(const void *a,const void *b){const item *x=a,*y=b;if(x->score<y->score)return -1;if(x->score>y->score)return 1;size_t nx=sdslen(x->key),ny=sdslen(y->key);int c=memcmp(x->key,y->key,nx<ny?nx:ny);return c?c:(nx>ny)-(nx<ny);}
static void verify(zbtreeSet *t,item *items,size_t n){item order[32];memcpy(order,items,n*sizeof(item));qsort(order,n,sizeof(item),compare);serverAssert(zbtreeLength(t)==n);zbtreeIterator it;serverAssert(zbtreeIteratorStart(t,0,&it));for(size_t r=0;r<n;r++){const unsigned char *p;size_t len;double score;serverAssert(zbtreeIteratorNext(&it,0,&p,&len,&score));serverAssert(len==sdslen(order[r].key)&&!memcmp(p,order[r].key,len)&&bits(score)==bits(order[r].score));serverAssert(zbtreeScore(t,order[r].key,&score)&&bits(score)==bits(order[r].score));serverAssert(zbtreeRank(t,order[r].key,0,NULL)==(long)r);serverAssert(zbtreeRank(t,order[r].key,1,NULL)==(long)(n-1-r));}serverAssert(!zbtreeIteratorNext(&it,0,NULL,NULL,NULL));}
int main(void){const size_t lens[]={8,16,319,320,321,1024};const double values[]={-DBL_MAX,-0x1p-1022,-0x1p-1074,-0.0,0.0,0x1p-1074,0x1p-1022,DBL_MAX};item items[24];zbtreeSet *t=zbtreeCreate();for(size_t i=0;i<24;i++){unsigned char key[1024];memset(key,0,lens[i%6]);key[0]=(unsigned char)i;key[lens[i%6]-1]=255;items[i]=(item){sdsnewlen(key,lens[i%6]),values[i%8]};zbtreeInsertPosition p;double old;serverAssert(!zbtreeFindForAdd(t,items[i].key,&old,&p));zbtreeInsertNew(t,items[i].score,items[i].key,&p);}verify(t,items,24);for(size_t k=0;k<96;k++){size_t id=(k*17)%24;double score=values[(k/3)%8];zbtreeInsertPosition p;double old;serverAssert(zbtreeFindForAdd(t,items[id].key,&old,&p));zbtreeUpdateScore(t,items[id].key,score,&p);items[id].score=score;verify(t,items,24);zbtreeSet *dup=zbtreeDup(t);verify(dup,items,24);zbtreeFree(dup);}zbtreeFree(t);for(size_t i=0;i<24;i++)sdsfree(items[i].key);puts("PASS 96 updates + clones; exact finite bits/signed zero/ties/binary lengths/order/rank/membership/ownership");}
